/**
 * @summary Upload media for a visit
 */
export const getUploadMediaUrl = (id: number) => {
  return `/api/visits/${id}/media`;
};

export const uploadMedia = async (
  id: number,
  uploadMediaBody: UploadMediaBody,
  options?: RequestInit,
): Promise<Media> => {
  const formData = new FormData();
  formData.append(`file`, uploadMediaBody.file);
  formData.append(`type`, uploadMediaBody.type);
  if (uploadMediaBody.caption !== undefined) {
    formData.append(`caption`, uploadMediaBody.caption);
  }

  return customFetch<Media>(getUploadMediaUrl(id), {
    ...options,
    method: "POST",
    body: formData,
  });
};

